-- Errata reading for H05: Reference definitions with obesity excluding E66.3 'Overweight'.
WITH obesity AS MATERIALIZED ( SELECT DISTINCT patient FROM records WHERE stream='conditions' AND ( (substr(json_extract(payload,'$.icd10'),1,3)='E66' AND json_extract(payload,'$.icd10')<>'E66.3') OR json_extract(payload,'$.snomed') IN ('162864005','408512008')) ), diabetes AS MATERIALIZED ( SELECT DISTINCT patient FROM records WHERE stream='conditions' AND ( substr(json_extract(payload,'$.icd10'),1,3) IN ('E08','E09','E10','E11','E13') OR json_extract(payload,'$.snomed') IN ('44054006','127013003','90781000119102','368581000119106','157141000119108')) ) SELECT COUNT(*) AS count FROM obesity WHERE patient NOT IN (SELECT patient FROM diabetes);
